require "yaml"
Dir.chdir "/app"

$keys = { "en" => {}, "ja" => {} }

def scope_for(path)
  rel = path.sub(%r{\A(saas/)?app/views/(mailers/)?}, "")
  parts = rel.split("/")
  parts[-1] = parts[-1].sub(/\A_/, "").sub(/\..*\z/, "")
  parts.join(".")
end

# f(path) { s from, to; k key, en, ja }
def f(path, &block)
  @path = path
  @scope = scope_for(path)
  @src = File.read(path)
  instance_eval(&block)
  File.write(path, @src)
end

def s(from, to)
  raise "#{@path}: not found: #{from.inspect}" unless @src.include?(from)
  @src = @src.gsub(from, to)
end

# Relative key (to file scope) or absolute when starting with "/"
def k(key, en, ja)
  full = key.start_with?("/") ? key[1..] : "#{@scope}.#{key}"
  add(full, en, ja)
end

def add(full, en, ja)
  { "en" => en, "ja" => ja }.each do |locale, value|
    h = $keys[locale]
    parts = full.split(".")
    parts[0..-2].each { |p| h = (h[p] ||= {}) }
    raise "conflict #{full}" if h[parts[-1]].is_a?(Hash)
    h[parts[-1]] = value
  end
end

def deep_merge(a, b)
  a.merge(b) { |_, x, y| x.is_a?(Hash) && y.is_a?(Hash) ? deep_merge(x, y) : y }
end

def deep_sort(h)
  h.sort_by { |k, _| k.to_s }.to_h.transform_values { |v| v.is_a?(Hash) ? deep_sort(v) : v }
end

at_exit do
  if $!.nil?
    $keys.each do |locale, tree|
      tree.each do |top, subtree|
        file = "config/locales/#{locale}/#{top}.yml"
        existing = File.exist?(file) ? (YAML.load_file(file)[locale] || {}) : {}
        merged = deep_sort(deep_merge(existing, { top => subtree }))
        File.write(file, YAML.dump({ locale => merged }, line_width: -1))
      end
    end
  end
end
